// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type CircularClockProps = Record<string, any>;

const CircularClock: React.FC<CircularClockProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  clockFaceColor = "#020617",
  clockBorderColor = "#2563eb",
  clockTextColor = "#3b82f6",
  hourHandColor = "#60a5fa",
  minuteHandColor = "#2563eb",
  centerPinColor = "#93c5fd",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global calculations
  const totalFrames = durationInSeconds * fps;
  const size = Math.min(width, height) * 0.75;
  
  // Animation Logic
  // Entrance spring animation for the clock
  const scale = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8 },
  });

  const opacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Time calculations:
  // Minute hand does exactly 2 full rotations (720 degrees)
  // Hour hand moves exactly 2 hours (60 degrees, as 360deg / 12 = 30deg per hour)
  const minuteRotation = interpolate(frame, [0, totalFrames], [0, 720]);
  const hourRotation = interpolate(frame, [0, totalFrames], [0, 60]);

  // Derived styling dimensions
  const borderThickness = size * 0.03;
  const centerPinSize = size * 0.05;
  const hourHandWidth = size * 0.025;
  const minuteHandWidth = size * 0.015;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          width: size,
          height: size,
          backgroundColor: clockFaceColor,
          borderRadius: "50%",
          border: `${borderThickness}px solid ${clockBorderColor}`,
          position: "relative",
          transform: `scale(${scale})`,
          opacity: opacity,
          boxShadow: "0 25px 50px -12px rgba(37, 99, 235, 0.25)",
          transition: "none",
        }}
      >
        {/* Number Indicators 1-12 */}
        {[...Array(12)].map((_, i) => {
          const num = i === 0 ? 12 : i;
          // Calculate position based on circle math (-PI/2 is top center)
          const angle = (i * Math.PI) / 6 - Math.PI / 2;
          const radius = size * 0.38; // Distance from center
          const x = size / 2 + radius * Math.cos(angle);
          const y = size / 2 + radius * Math.sin(angle);

          return (
            <div
              key={`number-${i}`}
              style={{
                position: "absolute",
                left: x,
                top: y,
                transform: "translate(-50%, -50%)",
                fontSize: size * 0.08,
                fontWeight: 700,
                color: clockTextColor,
                transition: "none",
              }}
            >
              {num}
            </div>
          );
        })}

        {/* Tick Marks */}
        {[...Array(60)].map((_, i) => {
          const isHour = i % 5 === 0;
          return (
            <div
              key={`tick-${i}`}
              style={{
                position: "absolute",
                top: 0,
                left: "50%",
                width: isHour ? size * 0.01 : size * 0.005,
                height: "100%",
                transform: `translateX(-50%) rotate(${i * 6}deg)`,
                transition: "none",
              }}
            >
              <div
                style={{
                  width: "100%",
                  height: isHour ? size * 0.04 : size * 0.02,
                  backgroundColor: clockTextColor,
                  opacity: isHour ? 1 : 0.3,
                  marginTop: borderThickness * 0.5,
                  transition: "none",
                }}
              />
            </div>
          );
        })}

        {/* Hour Hand */}
        <div
          style={{
            position: "absolute",
            bottom: "50%",
            left: `calc(50% - ${hourHandWidth / 2}px)`,
            width: hourHandWidth,
            height: size * 0.25,
            backgroundColor: hourHandColor,
            borderRadius: hourHandWidth / 2,
            transformOrigin: "bottom center",
            transform: `rotate(${hourRotation}deg)`,
            transition: "none",
            zIndex: 8,
            boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.3)",
          }}
        />

        {/* Minute Hand */}
        <div
          style={{
            position: "absolute",
            bottom: "50%",
            left: `calc(50% - ${minuteHandWidth / 2}px)`,
            width: minuteHandWidth,
            height: size * 0.4,
            backgroundColor: minuteHandColor,
            borderRadius: minuteHandWidth / 2,
            transformOrigin: "bottom center",
            transform: `rotate(${minuteRotation}deg)`,
            transition: "none",
            zIndex: 9,
            boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.3)",
          }}
        />

        {/* Center Pin */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: centerPinSize,
            height: centerPinSize,
            backgroundColor: centerPinColor,
            borderRadius: "50%",
            transform: "translate(-50%, -50%)",
            transition: "none",
            zIndex: 10,
            border: `${size * 0.005}px solid ${clockFaceColor}`,
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default CircularClock;